fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Pre-allocate a vector of the same length as `x`
    let mut weights = Vec::with_capacity(n);

    // For each position i:
    // - if it's the first or last index, weight = 0.5
    // - otherwise weight = 1.0
    for i in 0..n {
        let w = if i == 0 || i == n - 1 {
            0.5_f32
        } else {
            1.0_f32
        };
        weights.push(w);
    }

    weights
}